import 'package:flutter/material.dart';import '../../core/app_state.dart';
class TrashPage extends StatelessWidget{const TrashPage({super.key});@override Widget build(BuildContext c){final s=AppStateScope.of(c);return Scaffold(appBar:AppBar(title:const Text('ゴミ箱')),body:s.trash.isEmpty?const Center(child:Text('ゴミ箱は空です')):ListView.builder(itemCount:s.trash.length,itemBuilder:(c,i){final x=s.trash[i];return ListTile(leading:const Icon(Icons.delete_outline),title:Text(x.title),subtitle:Text('${x.type} · ${x.deletedAt.year}/${x.deletedAt.month}/${x.deletedAt.day}'),trailing:PopupMenuButton<String>(onSelected:(v)async{if(v=='restore'){final restored=s.restoreTrash(x);if(c.mounted)ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text(restored?'復元しました':'復元に失敗しました')));}else{final ok=await showDialog<bool>(context:c,builder:(d)=>AlertDialog(title:const Text('完全に削除しますか？'),content:const Text('この操作は元に戻せません。'),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('キャンセル')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('完全削除'))]));if(ok==true)s.deleteTrashForever(x);}},itemBuilder:(_)=>const[PopupMenuItem(value:'restore',child:Text('復元')),PopupMenuItem(value:'delete',child:Text('完全削除'))]));}));}}
